# D3.js v6 Force Simulation for Bubble Charts

## Overview
D3's force simulation module provides a physics-based layout engine for positioning nodes. It's ideal for bubble charts where elements need to be clustered by category without overlapping.

## Setup
```html
<script src="js/d3.v6.min.js"></script>
```

## Core Concepts

### Creating a Force Simulation
```javascript
const simulation = d3.forceSimulation(nodes)
  .force("charge", d3.forceManyBody().strength(-5))
  .force("center", d3.forceCenter(width / 2, height / 2))
  .force("collision", d3.forceCollide().radius(d => d.radius + 2))
  .force("x", d3.forceX(d => xScale(d.category)).strength(0.3))
  .force("y", d3.forceY(d => yScale(d.category)).strength(0.3))
  .on("tick", ticked);
```

### Key Forces

1. **forceCenter**: Pulls all nodes toward a center point
   ```javascript
   d3.forceCenter(width / 2, height / 2)
   ```

2. **forceCollide**: Prevents overlapping based on radius
   ```javascript
   d3.forceCollide().radius(d => radiusScale(d.value) + padding)
   ```

3. **forceX / forceY**: Cluster by category using position forces
   ```javascript
   // Create cluster positions
   const sectors = [...new Set(data.map(d => d.sector))];
   const clusterX = d3.scalePoint().domain(sectors).range([margin, width - margin]);
   const clusterY = d3.scalePoint().domain(sectors).range([margin, height - margin]);

   // Apply forces
   .force("x", d3.forceX(d => clusterX(d.sector)).strength(0.5))
   .force("y", d3.forceY(d => clusterY(d.sector)).strength(0.5))
   ```

4. **forceManyBody**: Repulsion/attraction between nodes
   ```javascript
   d3.forceManyBody().strength(-15)
   ```

### Tick Function
```javascript
function ticked() {
  bubbles
    .attr("cx", d => d.x)
    .attr("cy", d => d.y);
  labels
    .attr("x", d => d.x)
    .attr("y", d => d.y);
}
```

### Radius Scale for Market Cap
```javascript
const radiusScale = d3.scaleSqrt()
  .domain([d3.min(data, d => d.marketCap), d3.max(data, d => d.marketCap)])
  .range([8, 50]);
```

### Color Scale for Sectors
```javascript
const colorScale = d3.scaleOrdinal()
  .domain(sectors)
  .range(d3.schemeTableau10);
```

## Clustering Layout Strategy
For a 2-column or grid layout of sector clusters:
```javascript
const cols = Math.ceil(Math.sqrt(sectors.length));
const clusterPositions = {};
sectors.forEach((s, i) => {
  const col = i % cols;
  const row = Math.floor(i / cols);
  clusterPositions[s] = {
    x: margin + col * (width / cols) + (width / cols) / 2,
    y: margin + row * (height / Math.ceil(sectors.length / cols)) + ...
  };
});
```

## Performance Tips
- Use `.alphaDecay(0.02)` for smoother settling
- Use `.velocityDecay(0.3)` for faster convergence
- Stop simulation when alpha < alphaMin: `simulation.on("end", ...)`

# D3.js Tooltips and Interactive Elements

## Overview
Creating interactive tooltips and click-to-highlight interactions in D3.js v6.

## Tooltip Pattern

### HTML Tooltip (Recommended)
```javascript
// Create tooltip div
const tooltip = d3.select("body").append("div")
  .attr("class", "tooltip")
  .style("position", "absolute")
  .style("visibility", "hidden")
  .style("background", "rgba(0,0,0,0.8)")
  .style("color", "white")
  .style("padding", "8px 12px")
  .style("border-radius", "4px")
  .style("font-size", "13px")
  .style("pointer-events", "none");

// Attach to elements
bubbles
  .on("mouseover", function(event, d) {
    tooltip.style("visibility", "visible")
      .html(`<strong>${d.ticker}</strong><br>Name: ${d.name}<br>Sector: ${d.sector}`);
    d3.select(this).style("stroke", "#333").style("stroke-width", 2);
  })
  .on("mousemove", function(event) {
    tooltip
      .style("top", (event.pageY - 10) + "px")
      .style("left", (event.pageX + 10) + "px");
  })
  .on("mouseout", function() {
    tooltip.style("visibility", "hidden");
    d3.select(this).style("stroke", "none");
  });
```

### CSS for Tooltips
```css
.tooltip {
  position: absolute;
  background: rgba(0, 0, 0, 0.85);
  color: #fff;
  padding: 8px 12px;
  border-radius: 4px;
  font-size: 13px;
  pointer-events: none;
  z-index: 1000;
  box-shadow: 0 2px 8px rgba(0,0,0,0.3);
}
```

## Click Interaction: Linking Chart and Table

### Highlight on Click
```javascript
// In bubble chart
bubbles.on("click", function(event, d) {
  // Reset all highlights
  d3.selectAll(".bubble").classed("selected", false);
  d3.selectAll("tr").classed("highlighted", false);

  // Highlight clicked bubble
  d3.select(this).classed("selected", true);

  // Highlight corresponding table row
  d3.select(`#row-${d.ticker}`).classed("highlighted", true);

  // Scroll table row into view
  document.getElementById(`row-${d.ticker}`).scrollIntoView({
    behavior: 'smooth', block: 'nearest'
  });
});

// In data table
rows.on("click", function(event, d) {
  d3.selectAll(".bubble").classed("selected", false);
  d3.selectAll("tr").classed("highlighted", false);

  d3.select(this).classed("highlighted", true);
  d3.select(`#bubble-${d.ticker}`).classed("selected", true);
});
```

### CSS for Selection
```css
.bubble.selected {
  stroke: #333;
  stroke-width: 3px;
}

tr.highlighted {
  background-color: #fff3cd !important;
}
```

## D3 v6 Event Handling
In D3 v6, event handlers receive `(event, datum)` instead of `(datum, index, nodes)`:
```javascript
// D3 v6
.on("click", function(event, d) { ... })

// Access mouse position
event.pageX, event.pageY
```

## Legend
```javascript
const legend = svg.selectAll(".legend")
  .data(sectors)
  .join("g")
  .attr("class", "legend")
  .attr("transform", (d, i) => `translate(${width - 150}, ${20 + i * 22})`);

legend.append("rect")
  .attr("width", 15)
  .attr("height", 15)
  .attr("fill", d => colorScale(d));

legend.append("text")
  .attr("x", 20)
  .attr("y", 12)
  .text(d => d)
  .style("font-size", "12px");
```

# D3.js CSV Data Loading and Parsing

## Overview
D3.js provides built-in CSV parsing with `d3.csv()` for async loading and `d3.csvParse()` for string parsing.

## Loading CSV Files

### Basic Loading
```javascript
// D3 v6 uses Promises
const data = await d3.csv("data/stock-descriptions.csv");
// or
d3.csv("data/stock-descriptions.csv").then(data => {
  console.log(data); // Array of objects
});
```

### With Type Conversion
```javascript
const data = await d3.csv("data/stocks.csv", d => ({
  ticker: d.ticker,
  sector: d.sector,
  name: d["full name"],
  marketCap: d.marketCap ? +d.marketCap : null,
  employees: d.fullTimeEmployees ? +d.fullTimeEmployees : null,
  country: d.country || null,
  website: d.website || null,
  beta: d.beta ? +d.beta : null
}));
```

### Loading Multiple Files
```javascript
const [descriptions, priceData] = await Promise.all([
  d3.csv("data/stock-descriptions.csv"),
  d3.csv("data/indiv-stock/AAPL.csv")
]);
```

## Number Formatting

### Market Cap Formatting
```javascript
function formatMarketCap(value) {
  if (!value) return "N/A";
  const num = +value;
  if (num >= 1e12) return (num / 1e12).toFixed(2) + "T";
  if (num >= 1e9) return (num / 1e9).toFixed(2) + "B";
  if (num >= 1e6) return (num / 1e6).toFixed(2) + "M";
  return num.toLocaleString();
}
```

## CSV Column Access
When CSV has spaces or special characters in headers:
```javascript
// Access with bracket notation
d.["full name"]
d.["marketCap"]
```

## Handling Missing Data
ETFs may not have certain fields:
```javascript
const isETF = d.sector === "ETF";
const marketCap = isETF ? null : +d.marketCap;
```

# Creating Data Tables with D3.js

## Overview
D3.js can dynamically create HTML tables from data, enabling interactive features like sorting, filtering, and click-to-highlight.

## Basic Table Creation
```javascript
function createTable(data, containerId) {
  const container = d3.select(`#${containerId}`);

  const table = container.append("table")
    .attr("class", "data-table");

  // Header
  const thead = table.append("thead");
  thead.append("tr")
    .selectAll("th")
    .data(["Ticker", "Company Name", "Sector", "Market Cap"])
    .join("th")
    .text(d => d);

  // Body
  const tbody = table.append("tbody");
  const rows = tbody.selectAll("tr")
    .data(data)
    .join("tr")
    .attr("id", d => `row-${d.ticker}`)
    .attr("class", "table-row");

  // Cells
  rows.selectAll("td")
    .data(d => [d.ticker, d.name, d.sector, formatMarketCap(d.marketCap)])
    .join("td")
    .text(d => d);

  return rows;
}
```

## Scrollable Table with Fixed Header
```css
.table-container {
  max-height: 600px;
  overflow-y: auto;
  border: 1px solid #ddd;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
}

.data-table thead {
  position: sticky;
  top: 0;
  background: #f8f9fa;
  z-index: 1;
}

.data-table th, .data-table td {
  padding: 8px 12px;
  text-align: left;
  border-bottom: 1px solid #eee;
}

.data-table tbody tr:hover {
  background-color: #f0f0f0;
  cursor: pointer;
}
```

## Click Interaction
```javascript
rows.on("click", function(event, d) {
  // Remove previous highlights
  d3.selectAll(".table-row").classed("highlighted", false);
  d3.selectAll(".bubble").classed("selected", false);

  // Highlight this row
  d3.select(this).classed("highlighted", true);

  // Highlight corresponding bubble
  d3.select(`#bubble-${d.ticker}`).classed("selected", true);
});
```

## Scroll Into View
```javascript
function scrollToRow(ticker) {
  const row = document.getElementById(`row-${ticker}`);
  if (row) {
    row.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }
}
```

