(async function () {
  // ── Load and parse CSV data ──────────────────────────────────────────
  const raw = await d3.csv("data/stock-descriptions.csv");

  const data = raw.map(d => ({
    ticker: d.ticker,
    sector: d.sector,
    name: d["full name"],
    marketCap: d.marketCap ? +d.marketCap : null,
    country: d.country || null,
    website: d.website || null,
    isETF: d.sector === "ETF"
  }));

  // ── Helpers ──────────────────────────────────────────────────────────
  function formatMarketCap(value) {
    if (value == null || isNaN(value)) return "N/A";
    var num = +value;
    if (num >= 1e12) return (num / 1e12).toFixed(2) + "T";
    if (num >= 1e9) return (num / 1e9).toFixed(2) + "B";
    if (num >= 1e6) return (num / 1e6).toFixed(2) + "M";
    return num.toLocaleString();
  }

  // ── Sector colors ───────────────────────────────────────────────────
  var sectors = Array.from(new Set(data.map(d => d.sector)));
  var colorScale = d3.scaleOrdinal()
    .domain(sectors)
    .range(d3.schemeTableau10);

  // ── Radius scale (market cap) ───────────────────────────────────────
  var nonETF = data.filter(d => !d.isETF && d.marketCap);
  var radiusScale = d3.scaleSqrt()
    .domain([d3.min(nonETF, d => d.marketCap), d3.max(nonETF, d => d.marketCap)])
    .range([10, 52]);

  var ETF_RADIUS = 12;

  function getRadius(d) {
    return d.isETF ? ETF_RADIUS : radiusScale(d.marketCap);
  }

  // ── Bubble chart dimensions ─────────────────────────────────────────
  var chartDiv = document.getElementById("bubble-chart");
  var width = 700;
  var height = 620;
  var margin = { top: 10, right: 160, bottom: 10, left: 10 };
  var innerW = width - margin.left - margin.right;
  var innerH = height - margin.top - margin.bottom;

  // ── Cluster positions ───────────────────────────────────────────────
  var cols = Math.ceil(Math.sqrt(sectors.length));
  var rows = Math.ceil(sectors.length / cols);
  var clusterPositions = {};
  sectors.forEach(function (s, i) {
    var col = i % cols;
    var row = Math.floor(i / cols);
    clusterPositions[s] = {
      x: margin.left + (col + 0.5) * (innerW / cols),
      y: margin.top + (row + 0.5) * (innerH / rows)
    };
  });

  // ── SVG ─────────────────────────────────────────────────────────────
  var svg = d3.select("#bubble-chart")
    .append("svg")
    .attr("viewBox", "0 0 " + width + " " + height)
    .attr("preserveAspectRatio", "xMidYMid meet");

  // ── Tooltip ─────────────────────────────────────────────────────────
  var tooltip = d3.select("body").append("div")
    .attr("class", "tooltip");

  // ── Force simulation ────────────────────────────────────────────────
  var simulation = d3.forceSimulation(data)
    .force("x", d3.forceX(function (d) { return clusterPositions[d.sector].x; }).strength(0.45))
    .force("y", d3.forceY(function (d) { return clusterPositions[d.sector].y; }).strength(0.45))
    .force("charge", d3.forceManyBody().strength(-3))
    .force("collision", d3.forceCollide().radius(function (d) { return getRadius(d) + 2; }).strength(1))
    .alphaDecay(0.015)
    .velocityDecay(0.35)
    .on("tick", ticked);

  // ── Draw bubbles ────────────────────────────────────────────────────
  var bubbleGroups = svg.selectAll(".bubble-group")
    .data(data)
    .join("g")
    .attr("class", "bubble-group");

  var bubbles = bubbleGroups.append("circle")
    .attr("class", "bubble")
    .attr("id", function (d) { return "bubble-" + d.ticker; })
    .attr("r", function (d) { return getRadius(d); })
    .attr("fill", function (d) { return colorScale(d.sector); })
    .attr("fill-opacity", 0.85)
    .attr("stroke", function (d) { return d3.color(colorScale(d.sector)).darker(0.5); })
    .attr("stroke-width", 1);

  var labels = bubbleGroups.append("text")
    .attr("class", "bubble-label")
    .text(function (d) { return d.ticker; })
    .style("font-size", function (d) {
      var r = getRadius(d);
      return Math.max(7, Math.min(r * 0.55, 13)) + "px";
    });

  // ── Bubble interactions ─────────────────────────────────────────────
  bubbleGroups
    .on("mouseover", function (event, d) {
      if (d.isETF) return;
      tooltip.style("visibility", "visible")
        .html(
          "<strong>" + d.ticker + "</strong><br>" +
          "Name: " + d.name + "<br>" +
          "Sector: " + d.sector
        );
      d3.select(this).select("circle")
        .attr("fill-opacity", 1);
    })
    .on("mousemove", function (event) {
      tooltip
        .style("top", (event.pageY - 12) + "px")
        .style("left", (event.pageX + 14) + "px");
    })
    .on("mouseout", function (event, d) {
      tooltip.style("visibility", "hidden");
      if (!d3.select(this).select("circle").classed("selected")) {
        d3.select(this).select("circle")
          .attr("fill-opacity", 0.85);
      }
    })
    .on("click", function (event, d) {
      selectStock(d.ticker);
    });

  // ── Tick function ───────────────────────────────────────────────────
  function ticked() {
    bubbleGroups.attr("transform", function (d) {
      d.x = Math.max(margin.left + getRadius(d), Math.min(width - margin.right - getRadius(d), d.x));
      d.y = Math.max(margin.top + getRadius(d), Math.min(height - margin.bottom - getRadius(d), d.y));
      return "translate(" + d.x + "," + d.y + ")";
    });
  }

  // ── Legend ──────────────────────────────────────────────────────────
  var legendG = svg.append("g")
    .attr("transform", "translate(" + (width - margin.right + 16) + ", 20)");

  var legendItems = legendG.selectAll(".legend-item")
    .data(sectors)
    .join("g")
    .attr("class", "legend-item")
    .attr("transform", function (d, i) { return "translate(0," + (i * 24) + ")"; });

  legendItems.append("circle")
    .attr("r", 7)
    .attr("cx", 7)
    .attr("cy", 7)
    .attr("fill", function (d) { return colorScale(d); })
    .attr("fill-opacity", 0.85);

  legendItems.append("text")
    .attr("class", "legend-label")
    .attr("x", 20)
    .attr("y", 11)
    .text(function (d) { return d; });

  // ── Data table ──────────────────────────────────────────────────────
  var tablePanel = d3.select("#data-table");

  var tableContainer = tablePanel.append("div")
    .attr("class", "table-container");

  var table = tableContainer.append("table")
    .attr("class", "data-table");

  var thead = table.append("thead");
  thead.append("tr")
    .selectAll("th")
    .data(["Ticker", "Company Name", "Sector", "Market Cap"])
    .join("th")
    .text(function (d) { return d; });

  var tbody = table.append("tbody");

  var tableRows = tbody.selectAll("tr")
    .data(data)
    .join("tr")
    .attr("id", function (d) { return "row-" + d.ticker; })
    .attr("class", "table-row");

  tableRows.selectAll("td")
    .data(function (d) {
      return [d.ticker, d.name, d.sector, formatMarketCap(d.marketCap)];
    })
    .join("td")
    .text(function (d) { return d; });

  // ── Table click interaction ─────────────────────────────────────────
  tableRows.on("click", function (event, d) {
    selectStock(d.ticker);
  });

  // ── Shared selection logic ──────────────────────────────────────────
  var selectedTicker = null;

  function selectStock(ticker) {
    // Toggle if clicking the same stock
    if (selectedTicker === ticker) {
      clearSelection();
      return;
    }
    selectedTicker = ticker;

    // Clear previous
    d3.selectAll(".bubble").classed("selected", false).attr("fill-opacity", 0.85);
    d3.selectAll(".table-row").classed("highlighted", false);

    // Highlight bubble
    d3.select("#bubble-" + ticker)
      .classed("selected", true)
      .attr("fill-opacity", 1);

    // Highlight table row
    d3.select("#row-" + ticker)
      .classed("highlighted", true);

    // Scroll row into view
    var rowEl = document.getElementById("row-" + ticker);
    if (rowEl) {
      rowEl.scrollIntoView({ behavior: "smooth", block: "nearest" });
    }
  }

  function clearSelection() {
    selectedTicker = null;
    d3.selectAll(".bubble").classed("selected", false).attr("fill-opacity", 0.85);
    d3.selectAll(".table-row").classed("highlighted", false);
  }
})();

